  "data/question-catalog-dedupe.js": "(()=>{\n  const C=window.YKSQuestionCatalogV1;if(!C||C.__dedupeInstalled)return;\n  const rawAll=C.all.bind(C),rawRegister=C.register.bind(C);\n  const norm=s=>String(s??'').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9çğıöşü]+/g,'-').replace(/^-+|-+$/g,'');\n  const sourceKey=x=>x?.sourceFingerprint||[\n    norm(x?.provider),String(x?.year||''),norm(x?.exam),norm(x?.subject),norm(x?.collection),norm(x?.questionNo)\n  ].join('|');\n  const canonicalKey=x=>String(x?.duplicateOf||x?.canonicalQuestionId||x?.contentFingerprint||sourceKey(x)||x?.id||'');\n  const duplicateLog=[];\n\n  function indexes(rows=[]){\n    const byId=new Map(),bySource=new Map(),byCanonical=new Map();\n    for(const x of rows){\n      if(!x?.id)continue;\n      if(!byId.has(x.id))byId.set(x.id,x);\n      const sk=sourceKey(x);if(sk&&!bySource.has(sk))bySource.set(sk,x);\n      const ck=canonicalKey(x);if(ck&&!byCanonical.has(ck))byCanonical.set(ck,x);\n    }\n    return{byId,bySource,byCanonical};\n  }\n  function addAlternate(canonical,duplicate,reason){\n    if(!canonical||!duplicate)return;\n    canonical.alternateSources??=[];\n    const ref={provider:duplicate.provider,providerLabel:duplicate.providerLabel,collection:duplicate.collection,year:duplicate.year??null,exam:duplicate.exam,subject:duplicate.subject,questionNo:duplicate.questionNo,access:duplicate.access||null,duplicateId:duplicate.id,reason};\n    const key=JSON.stringify([ref.provider,ref.collection,ref.year,ref.exam,ref.subject,ref.questionNo,ref.access?.url||'']);\n    if(!canonical.alternateSources.some(a=>JSON.stringify([a.provider,a.collection,a.year,a.exam,a.subject,a.questionNo,a.access?.url||''])===key))canonical.alternateSources.push(ref);\n  }\n  function unique(rows=[]){\n    const out=[],seenId=new Set(),seenSource=new Set(),seenCanonical=new Set();\n    for(const x of rows){\n      if(!x?.id||seenId.has(x.id))continue;\n      const sk=sourceKey(x),ck=canonicalKey(x);\n      if((sk&&seenSource.has(sk))||(ck&&seenCanonical.has(ck)))continue;\n      seenId.add(x.id);if(sk)seenSource.add(sk);if(ck)seenCanonical.add(ck);\n      x.sourceFingerprint=x.sourceFingerprint||sk;\n      x.canonicalQuestionId=x.duplicateOf||x.canonicalQuestionId||x.id;\n      out.push(x);\n    }\n    return out;\n  }\n\n  C.all=()=>unique(rawAll());\n  C.allRecords=()=>[...rawAll()];\n  C.register=items=>{\n    const incoming=(items||[]).filter(x=>x?.id);\n    const idx=indexes(C.all());\n    const accepted=[];\n    for(const x of incoming){\n      const sk=sourceKey(x),ck=canonicalKey(x);\n      let canonical=null,reason='';\n      if(idx.byId.has(x.id)){canonical=idx.byId.get(x.id);reason='same-id'}\n      else if(sk&&idx.bySource.has(sk)){canonical=idx.bySource.get(sk);reason='same-source-question'}\n      else if(ck&&idx.byCanonical.has(ck)){canonical=idx.byCanonical.get(ck);reason=x.duplicateOf?'declared-duplicate':'same-content-fingerprint'}\n      if(canonical){\n        addAlternate(canonical,x,reason);\n        duplicateLog.push({duplicateId:x.id,canonicalId:canonical.id,reason,sourceFingerprint:sk,contentFingerprint:x.contentFingerprint||''});\n        continue;\n      }\n      x.sourceFingerprint=x.sourceFingerprint||sk;\n      x.canonicalQuestionId=x.duplicateOf||x.canonicalQuestionId||x.id;\n      accepted.push(x);idx.byId.set(x.id,x);if(sk)idx.bySource.set(sk,x);if(ck)idx.byCanonical.set(ck,x);\n    }\n    if(accepted.length)rawRegister(accepted);\n    return C.all();\n  };\n  C.getDuplicateRecords=()=>duplicateLog.map(x=>({...x}));\n  C.getCatalogCounts=()=>({records:rawAll().length,unique:C.all().length,duplicatesDetected:duplicateLog.length,alternateSources:C.all().reduce((n,x)=>n+(x.alternateSources?.length||0),0)});\n  C.makeSourceFingerprint=sourceKey;\n  C.makeCanonicalKey=canonicalKey;\n  C.__dedupeInstalled=true;\n})();",
  "data/question-catalog-policy-v2.js": "(()=>{\n  const C=window.YKSQuestionCatalogV1;if(!C)return;\n  const norm=s=>String(s||'').toLocaleLowerCase('tr-TR').replace(/[^a-z0-9çğıöşü]+/g,' ').trim();\n  const words=s=>new Set(norm(s).split(' ').filter(x=>x.length>2));\n  const overlap=(a,b)=>{const A=words(a),B=words(b);let n=0;A.forEach(x=>B.has(x)&&n++);return n};\n  const providerRank=x=>x?.provider==='OSYM'?30:x?.provider==='MEB_OGM'?20:x?.sourceKind==='uploaded'?10:0;\n  const solvedEvents=()=> (typeof state!=='undefined'&&Array.isArray(state.studyEvents)?state.studyEvents:window.state?.studyEvents||[]).filter(x=>x?.source==='source-question-result'&&x?.meta?.catalogId);\n  const solvedIds=()=>new Set(solvedEvents().map(x=>x.meta.catalogId));\n  const rowTrack=x=>x?.track||'main';\n  const needsTopicReview=x=>x?.verification?.topic==='needs-manual-review-text-extraction-loss';\n\n  function trackEligible(x,q={}){\n    if(q.track)return rowTrack(x)===q.track;\n    if(q.includeAlternateTrack===true)return true;\n    return rowTrack(x)!=='alternate-track';\n  }\n\n  function topicEligible(x,q={}){\n    return !norm(q.topic)||!needsTopicReview(x);\n  }\n\n  function relevance(x,q={}){\n    const query=norm([q.topic,q.curriculumOutcome,q.shortSolution].join(' '));\n    const item=norm([x.topic,...(x.subtopics||[]),...(x.tags||[])].join(' '));\n    let s=overlap(query,item)*18;\n    const qt=norm(q.topic),xt=norm(x.topic);\n    if(qt&&xt===qt)s+=90;\n    else if(qt&&(xt.includes(qt)||qt.includes(xt)))s+=55;\n    if(/üçgen/.test(qt)&&/üçgen/.test(item))s+=35;\n    if(/trigonom/.test(qt)&&/trigonom/.test(item))s+=40;\n    if(/benzer/.test(qt)&&/benzer/.test(item))s+=40;\n    if(/pisagor|dik üçgen/.test(qt)&&/pisagor|dik üçgen/.test(item))s+=40;\n    if(q.visualPreferred&&x.visual)s+=8;\n    return s;\n  }\n\n  function eligible(q={}){\n    const done=solvedIds();\n    return C.all().filter(x=>!done.has(x.id))\n      .filter(x=>trackEligible(x,q))\n      .filter(x=>topicEligible(x,q))\n      .filter(x=>!q.exam||String(x.exam||'').toUpperCase()===String(q.exam||'').toUpperCase())\n      .filter(x=>!q.subject||norm(x.subject)===norm(q.subject))\n      .map(x=>({...x,_match:relevance(x,q),_year:Number(x.year||0)}))\n      .filter(x=>!norm(q.topic)||x._match>0);\n  }\n\n  function findNextBatch(q={},limit=5){\n    const rows=eligible(q);if(!rows.length)return[];\n    const newest=Math.max(...rows.map(x=>x._year));\n    return rows.filter(x=>x._year===newest)\n      .sort((a,b)=>b._match-a._match||providerRank(b)-providerRank(a)||String(a.questionNo||'').localeCompare(String(b.questionNo||''),'tr'))\n      .slice(0,limit);\n  }\n\n  function progress(q={}){\n    const all=C.all()\n      .filter(x=>trackEligible(x,q))\n      .filter(x=>topicEligible(x,q))\n      .filter(x=>!q.exam||String(x.exam||'').toUpperCase()===String(q.exam||'').toUpperCase())\n      .filter(x=>!q.subject||norm(x.subject)===norm(q.subject));\n    const done=solvedIds();\n    const relevant=all.map(x=>({...x,_match:relevance(x,q)})).filter(x=>!norm(q.topic)||x._match>0);\n    const years=[...new Set(relevant.map(x=>Number(x.year||0)))].sort((a,b)=>b-a);\n    return{total:relevant.length,solved:relevant.filter(x=>done.has(x.id)).length,remaining:relevant.filter(x=>!done.has(x.id)).length,years};\n  }\n\n  C.findNextBatch=findNextBatch;\n  C.getSolvedIds=solvedIds;\n  C.getProgress=progress;\n  C.selectionPolicy={mode:'library-only',order:['topic-match','unsolved','year-desc','provider','relevance'],yearGate:true,providerOrder:['OSYM','MEB_OGM','uploaded-pdf'],openedIsSolved:false,resultMarksSolved:true,defaultTrack:'main',alternateTrackOptIn:true,strictTopicSkipsManualReview:true};\n})();\n",
