export const FILE_LIST = Object.freeze(Object.keys(PROJECT_FILES).sort());
export function getFile(path){ return PROJECT_FILES[path] ?? null; }
export function searchProject(term){ const q=String(term).toLowerCase(); return FILE_LIST.filter(p => p.toLowerCase().includes(q) || PROJECT_FILES[p].toLowerCase().includes(q)); }
export default PROJECT_FILES;
